out['consistent']=(len(csvrows)==292 and len(xrows)==292 and ws.max_column==32 and c218.get('الرقم المرجعي الرسمي') in ('',None) and c218.get(keycol)=='investsaudi:44865' and x218.get(keycol)=='investsaudi:44865' and c228.get('مدة العقد (سنة)') in ('5','5.0') and c228.get('العملة') in ('',None) and c228.get(keycol)=='ncp:foodsafetylabs' and x228.get('مدة العقد (سنة)') in (5,5.0) and c230.get('المساحة (م²)') in ('160','160.0') and c230.get('مدة العقد (سنة)') in ('5','5.0') and c230.get('الرقم المرجعي الرسمي')=='06-26-183737-49010' and c230.get('العملة') in ('',None) and x230.get('الرقم المرجعي الرسمي')=='06-26-183737-49010' and next(c for c in ws.iter_rows(min_row=7,values_only=False) if c[0].value==x230.get('اسم الفرصة'))[19].data_type=='s' and next(c for c in ws.iter_rows(min_row=7,values_only=False) if c[0].value==x230.get('اسم الفرصة'))[19].number_format=='@' and c230.get(keycol)=='furas:06-26-183737-49010 | investsaudi:54952' and x230.get(keycol)==c230.get(keycol))
